import { readFileSync, writeFileSync, symlinkSync } from "node:fs"
import { join, dirname, resolve } from "node:path"
import { gunzipSync } from "node:zlib"
import { deepStrictEqual } from "node:assert"
import { createHash } from "node:crypto"
const repo = resolve(process.argv[2] ?? process.cwd())
const dir = import.meta.dir
try { symlinkSync(join(repo,"node_modules"),join(dir,"node_modules")) } catch(error: any) { if(error.code!=="EEXIST") throw error }
const base=join(repo,"lib/autorouter-pipelines/AutoroutingPipeline9_Parallel/authoritative-drc-fork")
const checkerPath=join(base,"native/lib/check-traces-are-contiguous/check-traces-are-contiguous.ts")
const indexPath=join(base,"native/lib/util/create-indexed-pcb-connectivity-map.ts")
const viaPath=join(base,"native/lib/util/get-via-and-pour-connections.ts")
const counterPath=join(dir,"counter.ts")
writeFileSync(counterPath, `import { doesLineIntersectLine } from ${JSON.stringify(join(repo,"node_modules/circuit-json-to-connectivity-map/node_modules/@tscircuit/math-utils/dist/index.js"))}; export function countPair(a:any,b:any,expected:boolean):void { let visits=0,value=false; outer: for(let i=0;i<a.route.length-1;i++){ const p=a.route[i],q=a.route[i+1]; if(p.route_type!=="wire"||q.route_type!=="wire")continue;for(let j=0;j<b.route.length-1;j++){ const r=b.route[j],t=b.route[j+1];if(r.route_type!=="wire"||t.route_type!=="wire")continue; visits++;if(doesLineIntersectLine([p,q],[r,t],{lineThickness:(p.width+r.width)/2})){value=true;break outer}}} if(value!==expected)throw new Error("Native pair counter differs");census.tracePairSegmentPredicateVisits=(census.tracePairSegmentPredicateVisits??0)+visits; census.tracePairMissRows[census.tracePairMissRows.length-1][3]=visits; }; export let census: any = {}; export function reset(): void { census={tracePairQueries:0,tracePairMisses:0,polygonQueries:0,polygonMisses:0} }; export function snap(memo:any): any { return memo===undefined?null:{...memo.diagnostics} }\n`)
const patchImports = (text:string, source:string, substitutions:Record<string,string>):string => text.replace(/from\s+"(\.[^"]+)"/g,(_match,spec)=>`from ${JSON.stringify(substitutions[spec]??resolve(dirname(source),spec))}`)
let via=readFileSync(viaPath,"utf8")
via=via.replace(`      if (primitiveMemo\n        ? primitiveMemo.getOrCompute("polygon-contact"`, `      census.polygonQueries++\n      if (primitiveMemo\n        ? primitiveMemo.getOrCompute("polygon-contact"`)
via=via.replace(`(): boolean => touches(a.polygon, b.polygon)`, `(): boolean => { census.polygonMisses++; const value=touches(a.polygon, b.polygon); census.polygonMissRows ??= []; census.polygonMissRows.push([a.polygon.edges.size,b.polygon.edges.size,value]); return value }`)
writeFileSync(join(dir,"via.ts"), `import {census} from ${JSON.stringify(counterPath)}\n`+patchImports(via,viaPath,{}))
let index=readFileSync(indexPath,"utf8")
index=index.replace(`      if (primitiveMemo\n        ? primitiveMemo.getOrCompute("trace-pair"`, `      census.tracePairQueries++\n      if (primitiveMemo\n        ? primitiveMemo.getOrCompute("trace-pair"`)
index=index.replace(`(): boolean => map._arePcbTracesConnected(traces[i], traces[j])`, `(): boolean => { census.tracePairMisses++; const value=map._arePcbTracesConnected(traces[i], traces[j]); census.tracePairMissRows ??= []; census.tracePairMissRows.push([traces[i].route.length,traces[j].route.length,value]); countPair(traces[i],traces[j],value); return value }`)
writeFileSync(join(dir,"index.ts"), `import {census,countPair} from ${JSON.stringify(counterPath)}\n`+patchImports(index,indexPath,{"./get-via-and-pour-connections":join(dir,"via.ts")}))
let checker=readFileSync(checkerPath,"utf8")
checker=checker.replace(`  pcbConnectivityMap ??= createIndexedPcbConnectivityMap(circuitJson, primitiveMemo, scaledPolygonMemo)`, `  census.graphBefore=snap(primitiveMemo)\n  pcbConnectivityMap ??= createIndexedPcbConnectivityMap(circuitJson, primitiveMemo, scaledPolygonMemo)\n  census.graphAfter=snap(primitiveMemo)`)
checker=checker.replace(`  const padInventoryId = primitiveMemo ? primitiveMemo.intern([...padMap]) : 0`, `  census.endpointBefore=snap(primitiveMemo)\n  const padInventoryId = primitiveMemo ? primitiveMemo.intern([...padMap]) : 0`)
checker=checker.replace(`  const physicallyConnectedTracesByTraceId = new Map`, `  census.endpointAfter=snap(primitiveMemo)\n  const physicallyConnectedTracesByTraceId = new Map`)
checker=checker.replace(`  const useExpectedPortMemo = privatelyOwnedMemo &&`, `  census.privatelyOwned=privatelyOwnedMemo\n  const useExpectedPortMemo = privatelyOwnedMemo &&`)
checker=checker.replace(`  let scaledPolygonMemo: ScaledConductorPolygonMemo | undefined`, `  census.expectedMemo=useExpectedPortMemo\n  let scaledPolygonMemo: ScaledConductorPolygonMemo | undefined`)
checker=checker.replace(`  return errors\n}`, `  census.finalMemo=snap(primitiveMemo)\n  return errors\n}`)
writeFileSync(join(dir,"checker.ts"), `import {census,snap} from ${JSON.stringify(counterPath)}\n`+patchImports(checker,checkerPath,{"../util/create-indexed-pcb-connectivity-map":join(dir,"index.ts")}))
const {initializeReferenceDrcRuntime}=await import(join(base,"initializeReferenceDrcRuntime.ts"))
const {checkViaTraceClearanceWithLazyCenters}=await import(join(base,"checkViaTraceClearanceWithLazyCenters.ts"))
const {getDrcErrors}=await import(join(repo,"lib/testing/getDrcErrors.ts"))
await initializeReferenceDrcRuntime()
const {createPrivatelyMemoizedTraceContinuityChecker}=await import(join(dir,"checker.ts"))
const counts=await import(counterPath)
const nativeCheck=createPrivatelyMemoizedTraceContinuityChecker()
const fixture=join(repo,"tests/fixtures/reference-drc-srj18/sample015-native-reference.json.gz")
const captures=JSON.parse(gunzipSync(readFileSync(fixture)).toString())
const rows:any[]=[]
for(const capture of captures.records){
 counts.reset()
 const result=getDrcErrors(structuredClone(capture.circuitJson),{...capture.options,traceContinuityChecker:nativeCheck,viaTraceChecker:(circuit:any,options:any)=>checkViaTraceClearanceWithLazyCenters(circuit,{...options,enableAxisRejection:true,enableConnectivityMemo:true})})
 deepStrictEqual(JSON.parse(JSON.stringify(result)),capture.expected)
 if(counts.census.privatelyOwned!==true||counts.census.expectedMemo!==true) throw new Error("private native guard not admitted")
 rows.push({number:capture.number,errors:capture.expected.errors.length,...structuredClone(counts.census)})
}
const totals={tracePairQueries:0,tracePairMisses:0,polygonQueries:0,polygonMisses:0}
for(const row of rows) for(const key of Object.keys(totals)) totals[key]+=row[key]
const hashes=Object.fromEntries([checkerPath,indexPath,viaPath,fixture].map(path=>[path.slice(repo.length+1),createHash("sha256").update(readFileSync(path)).digest("hex")]))
writeFileSync(join(dir,"census.json"),JSON.stringify({kind:"time-free operation census; all17 native saved errors exact",hashes,totals,rows},null,2)+"\n")
console.log(JSON.stringify({records:rows.length,allSavedErrorsExact:true,totals,output:join(dir,"census.json")}))
